// Generates mark.ts: the Skycord headphones mark as persona-icons parts on the engine's 24-unit grid.
// The source is the `i-mark` symbol in index.html (viewBox 256). Its single evenodd path is split into
// the headphone band, the dome (head) and two eye circles, so the engine can blink and move the eyes.
//   node scale-mark.mjs > mark.ts
const K = 24 / 256;
const r = (n) => Math.round(n * 1000) / 1000;

function scalePath(d) {
  return d.replace(/([MmLlHhVvAaZz])([^MmLlHhVvAaZz]*)/g, (_, cmd, rest) => {
    const nums = (rest.match(/-?\d*\.?\d+(?:e-?\d+)?/g) || []).map(Number);
    if (!nums.length) return cmd;
    const out = [];
    if (cmd === 'A' || cmd === 'a') {
      for (let i = 0; i < nums.length; i += 7) {
        const [rx, ry, rot, large, sweep, x, y] = nums.slice(i, i + 7);
        out.push(r(rx * K), r(ry * K), rot, large, sweep, r(x * K), r(y * K));
      }
    } else out.push(...nums.map((n) => r(n * K)));
    return cmd + out.join(' ');
  });
}

const dome = 'M56,150A72,72 0 0 1 200,150V170A48,48 0 0 1 152,218H104A48,48 0 0 1 56,170Z';
const band = 'M12,170V130A17,17 0 0 1 26.47,113.19A108,108 0 0 1 229.53,113.19A17,17 0 0 1 244,130V170A17,17 0 0 1 210,170V130A17,17 0 0 1 212.99,120.38A90,90 0 0 0 43.01,120.38A17,17 0 0 1 46,130V170A17,17 0 0 1 12,170Z';
const eye = (cx) => ['circle', { cx: String(r(cx * K)), cy: String(r(156 * K)), r: String(r(14 * K)), class: 'pi-mark-eye' }];

const nodes = [
  ['path', { d: scalePath(band), fill: 'currentColor', stroke: 'none' }],
  ['path', { d: scalePath(dome), fill: 'currentColor', stroke: 'none' }],
  eye(104),
  eye(152),
];

console.log(`// GENERATED by scale-mark.mjs from the i-mark symbol in index.html. Do not edit by hand.
import type { Rig } from './types';
import { presets as P } from './presets';

/** The Skycord mark as persona-icons parts, on the engine's 24-unit grid. */
export const markNodes: [string, Record<string, string>][] = ${JSON.stringify(nodes, null, 1)};

/** Rig for the mark: the band and head are the body, the two circles are native eyes. */
export const markRig: Rig = {
  name: 'skycord',
  pivot: '50% 62%',
  parts: {
    band: { index: 0, match: 'M1.125' },
    head: { index: 1, match: 'M5.25' },
    eyeL: { index: 2, match: 'circle' },
    eyeR: { index: 3, match: 'circle' },
  },
  // No mouth: the mark has none. Drawn eyes (happy, squint, dizzy) replace the circles for an expression.
  face: { eyes: [[${r(104 * K)}, ${r(156 * K)}], [${r(152 * K)}, ${r(156 * K)}]], nativeEyes: ['eyeL', 'eyeR'], size: 1 },
  // What the mark does that is unique to it: it bounces to the beat, the band pulsing with it.
  signature: (s, i) => ({
    body: P.hop(s, 0.4 + 0.4 * i),
    parts: {
      band: { frames: [{ transform: 'translateY(-0.5px) scale(1.04)', offset: 0.4 }, { transform: 'translateY(0px) scale(1)' }], duration: 480, easing: 'ease-out' },
    },
  }),
};
`);
